75	const SELF = fileURLToPath(import.meta.url);
76	const LANE = resolve(dirname(SELF), '..');
77	const DEFAULT_REGISTRY = '.ufo/pins/source-dupes.json';
78	const DEFAULT_SOURCES = 'corpus/SOURCES.md';
79	const SID = /^S[0-9]{3,}$/;
