86	// Same normalization as scripts/sources-census.sh url_of(): strip scheme,
87	// fragment and one trailing slash; lowercase the host only.
88	function urlOf(sourceCell) {
89	  const m = sourceCell.match(/https?:\/\/[^\s|]+/);
90	  if (!m) return '';
91	  let u = m[0];
92	  u = u.replace(/#[^ ]*$/, '').replace(/\/$/, '').replace(/^[A-Za-z]+:\/\//, '');
93	  const n = u.indexOf('/');
94	  return n ? u.slice(0, n).toLowerCase() + u.slice(n) : u.toLowerCase();
95	}
