97	function loadRegistry(regPath) {
98	  let raw;
99	  try {
100	    if (!lstatSync(regPath).isFile()) {
101	      return { ok: false, reason: 'registry not a regular file' };
102	    }
103	    raw = readFileSync(regPath);
104	  } catch (e) {
105	    return { ok: false, reason: `registry unreadable: ${e.code || 'EIO'}` };
106	  }
107	  let doc;
108	  try {
109	    doc = JSON.parse(raw.toString('utf8'));
110	  } catch {
111	    return { ok: false, reason: 'registry not valid JSON' };
112	  }
113	  if (!doc || typeof doc !== 'object' || Array.isArray(doc)) {
114	    return { ok: false, reason: 'registry not an object' };
115	  }
116	  if (doc.version !== 1) {
117	    return { ok: false, reason: `registry version ${JSON.stringify(doc.version)} !== 1` };
118	  }
119	  if (!Array.isArray(doc.known)) {
120	    return { ok: false, reason: 'registry known not an array' };
121	  }
122	  const covered = new Set();
123	  for (const k of doc.known) {
124	    if (!k || typeof k !== 'object' || !Array.isArray(k.ids) || k.ids.length < 2
125	        || k.ids.some((id) => typeof id !== 'string' || !SID.test(id))
126	        || new Set(k.ids).size !== k.ids.length
127	        || typeof k.url !== 'string' || k.url.length === 0
128	        || typeof k.why !== 'string' || k.why.length === 0) {
129	      return { ok: false, reason: 'a known entry lacks valid ids(>=2, unique, S###)/url/why' };
130	    }
131	    for (const id of k.ids) {
132	      if (covered.has(id)) {
133	        return { ok: false, reason: `row id ${JSON.stringify(id)} covered by two known entries` };
134	      }
135	      covered.add(id);
136	    }
137	  }
138	  return { ok: true, known: doc.known };
139	}
140	
141	// Rows in the Registry section only: `## Registry` until the next top heading;
142	// 0–3 leading spaces tolerated, 4+ is indented code (census parser note).
143	function loadRows(srcPath) {
144	  let raw;
145	  try {
146	    if (!lstatSync(srcPath).isFile()) {
147	      return { ok: false, reason: 'sources doc not a regular file' };
148	    }
149	    raw = readFileSync(srcPath, 'utf8');
150	  } catch (e) {
151	    return { ok: false, reason: `sources doc unreadable: ${e.code || 'EIO'}` };
152	  }
153	  const rows = [];
154	  let inRegistry = false;
155	  let seenRegistry = false;
156	  for (const line0 of raw.split('\n')) {
157	    if (/^ {0,3}##[ \t]/.test(line0)) {
158	      const h = line0.replace(/^ {0,3}/, '').replace(/^##[ \t]+/, '').trim();
159	      inRegistry = h === 'Registry';
160	      if (inRegistry) seenRegistry = true;
161	      continue;
162	    }
163	    if (/^ {0,3}#[ \t]/.test(line0)) { inRegistry = false; continue; }
164	    if (!inRegistry || !/^ {0,3}\|/.test(line0)) continue;
165	    const cells = line0.replace(/^ {0,3}/, '').split('|').map((c) => c.trim());
166	    if (cells.length !== 13) continue;                       // NF=13 like the census
167	    if (/^-+$/.test(cells[2].replace(/\s/g, '')) || /^-+$/.test((cells[1] || '').replace(/\s/g, ''))) continue; // separator
168	    const id = cells[1];
169	    if (!SID.test(id)) continue;
170	    rows.push({ id, scope: cells[5], url: urlOf(cells[2]) });
171	  }
172	  if (!seenRegistry) {
173	    return { ok: false, reason: 'sources doc carries no ## Registry section' };
174	  }
175	  if (rows.length === 0) {
176	    return { ok: false, reason: 'sources doc carries no S### rows in Registry' };
177	  }
178	  return { ok: true, rows };
179	}
