181	// Live duplicate groups: same normalized URL, differing scope cells (W04).
182	function duplicateGroups(rows) {
183	  const byUrl = new Map();
184	  for (const r of rows) {
185	    if (!r.url) continue;
186	    if (!byUrl.has(r.url)) byUrl.set(r.url, []);
187	    byUrl.get(r.url).push(r);
188	  }
189	  const groups = [];
190	  for (const [url, members] of byUrl) {
191	    if (members.length < 2) continue;
192	    const scopes = new Set(members.map((m) => m.scope));
193	    if (scopes.size < 2) continue;
194	    groups.push({ url, ids: members.map((m) => m.id).sort() });
195	  }
196	  groups.sort((a, b) => a.url.localeCompare(b.url));
197	  return groups;
198	}
199	
200	const key = (ids) => ids.slice().sort().join('+');
201	
202	function evaluate(registryPath, sourcesPath) {
203	  const reg = loadRegistry(registryPath);
204	  if (!reg.ok) {
205	    return { verdict: 'FAIL-CLOSED', reason: reg.reason, exit: 2 };
206	  }
207	  const src = loadRows(sourcesPath);
208	  if (!src.ok) {
209	    return { verdict: 'FAIL-CLOSED', reason: src.reason, exit: 2 };
210	  }
211	  const live = duplicateGroups(src.rows);
212	  const liveByKey = new Map(live.map((g) => [key(g.ids), g]));
213	  const liveByUrl = new Map(live.map((g) => [g.url, g]));
214	  const knownIds = new Map();
215	  const bad = [];
216	  for (const k of reg.known) {
217	    knownIds.set(key(k.ids), k);
218	    const g = liveByKey.get(key(k.ids));
219	    if (!g) {
220	      // Does any live group share this URL or overlap members? Then the pin's
221	      // shape is wrong rather than simply stale.
222	      const overlap = live.find((lg) => lg.ids.some((id) => k.ids.includes(id)));
223	      if (overlap) {
224	        bad.push(`known-mismatch:${k.url} live=${overlap.ids.join(',')}`);
225	      } else if (liveByUrl.has(k.url)) {
226	        bad.push(`known-mismatch:${k.url} live=${liveByUrl.get(k.url).ids.join(',')}`);
227	      } else {
228	        bad.push(`stale-known:${k.ids.join(',')}`);
229	      }
230	    } else if (g.url !== k.url) {
231	      bad.push(`known-mismatch:${k.url} live-url=${g.url}`);
232	    }
233	  }
234	  for (const g of live) {
235	    if (!knownIds.has(key(g.ids))) {
236	      bad.push(`new-duplicate:${g.url} ids=${g.ids.join(',')}`);
237	    }
238	  }
239	  if (bad.length > 0) {
240	    return { verdict: 'DRIFT', groups: live.length, known: reg.known.length, bad, exit: 1 };
241	  }
242	  return { verdict: 'CLEAN', groups: live.length, known: reg.known.length, exit: 0 };
243	}
