245	function emit(result) {
246	  if (result.verdict === 'CLEAN') {
247	    process.stdout.write(`SOURCE_DUPES: CLEAN groups=${result.groups} known=${result.known}\n`);
248	  } else if (result.verdict === 'DRIFT') {
249	    for (const b of result.bad.slice(1)) process.stdout.write(`SOURCE_DUPES: note ${b}\n`);
250	    process.stdout.write(`SOURCE_DUPES: DRIFT groups=${result.groups} known=${result.known} bad=${result.bad.length} first=${result.bad[0]}\n`);
251	  } else {
252	    process.stdout.write(`SOURCE_DUPES: FAIL-CLOSED reason=${result.reason}\n`);
253	  }
254	  process.exit(result.exit);
255	}
