257	function selftest() {
258	  const root = mkdtempSync(join(tmpdir(), 'source-dupes-st.'));
259	  const results = [];
260	  const pass = (name, ok, detail) => {
261	    results.push({ name, ok });
262	    process.stdout.write(`case ${name}: ${ok ? 'PASS' : `FAIL ${detail || ''}`}\n`);
263	  };
264	  const run = (args, opts = {}) => spawnSync(process.execPath, [SELF, ...args],
265	    { encoding: 'utf8', timeout: 60_000, ...opts });
266	  const last = (r) => `${r.stdout || ''}`.trim().split('\n').pop() || '';
267	
268	  const HEADER = '| id | source | kind | tier | scope | anchor | teaches | status | opened | recheck | used-by |\n'
269	    + '|---|---|---|---|---|---|---|---|---|---|---|\n';
270	  const row = (id, url, scope) =>
271	    `| ${id} | title — ${url} | docs | B | ${scope} | §1 | t | mined | 2026-01-01 | 90d | p |\n`;
272	
273	  const mkdirp = (d) => { rmSync(d, { recursive: true, force: true }); mkdirSync(d, { recursive: true }); };
274	  const fixture = (dir, rows, known) => {
275	    mkdirp(dir);
276	    writeFileSync(join(dir, 'sources.md'), '## Registry\n' + HEADER + rows.join(''));
277	    writeFileSync(join(dir, 'reg.json'), JSON.stringify({ version: 1, known }, null, 2));
278	    return { reg: join(dir, 'reg.json'), src: join(dir, 'sources.md') };
279	  };
280	
281	  const baseRows = [
282	    row('S001', 'https://a.example/x', 's1'),
283	    row('S002', 'https://a.example/x', 's2'),   // dup group A (S001,S002)
284	    row('S003', 'https://b.example/y', 's3'),
285	    row('S004', 'https://c.example/z', 's4'),
286	    row('S005', 'https://c.example/z', 's4'),   // same url SAME scope — E04 family, not W04
287	  ];
288	  const baseKnown = [{ ids: ['S001', 'S002'], url: 'a.example/x', why: 'pre-rule duplicate, kept' }];
289	
290	  try {
291	    // case 1 — clean: one pinned group, same-scope same-url ignored. CLEAN groups=1 known=1
292	    {
293	      const d = join(root, 'd1'); const f = fixture(d, baseRows, baseKnown);
294	      const r = run(['--registry', f.reg, '--sources', f.src]);
295	      pass('clean', r.status === 0 && last(r) === 'SOURCE_DUPES: CLEAN groups=1 known=1',
296	        `exit=${r.status} last=${JSON.stringify(last(r))}`);
297	    }
298	    // case 2 — new duplicate: DRIFT new-duplicate, exit 1
299	    {
300	      const d = join(root, 'd2'); const f = fixture(d,
301	        [...baseRows, row('S006', 'https://d.example/w', 's5'), row('S007', 'https://d.example/w', 's6')],
302	        baseKnown);
303	      const r = run(['--registry', f.reg, '--sources', f.src]);
304	      pass('new-duplicate', r.status === 1 && last(r).includes('new-duplicate:d.example/w ids=S006,S007'),
305	        `exit=${r.status} last=${JSON.stringify(last(r))}`);
306	    }
307	    // case 3 — stale known: pinned group no longer duplicates. DRIFT stale-known
308	    {
309	      const d = join(root, 'd3'); const f = fixture(d,
